glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform sampler2D bandTex;
uniform sampler2D maskTex;

uniform PROPERTIES {
  vec4 glowColor;
  vec4 glowParams;
  vec4 edgeShape;
  vec4 edgeProfile;
  float pulseSpeed;
  float bandTexReady;
};

float mapBandTexU(float u, float widthX) {
  return clamp((u - 0.5) * widthX + 0.5, 0.0, 1.0);
}

vec4 sampleEdgeBand(float distFromEdge, float bandHeight, float widthX) {
  float t = clamp(distFromEdge / max(0.001, bandHeight), 0.0, 1.0);
  float texU = mapBandTexU(clamp(v_uv0.x, 0.0, 1.0), widthX);

  if (bandTexReady < 0.5) {
    return vec4(0.0);
  }

  vec4 band = texture2D(bandTex, vec2(texU, t));
  vec4 bandL = texture2D(bandTex, vec2(clamp(texU - 0.004, 0.0, 1.0), t));
  vec4 bandR = texture2D(bandTex, vec2(clamp(texU + 0.004, 0.0, 1.0), t));
  if (bandL.a > band.a) band = bandL;
  if (bandR.a > band.a) band = bandR;
  return band;
}

void main () {
  float glowAlpha = clamp(glowParams.x, 0.0, 1.0);
  float bandHeight = clamp(glowParams.y, 0.0, 0.1);
  float edgeFeather = clamp(glowParams.z, 0.005, 0.08);
  float pulseAmount = clamp(glowParams.w, 0.0, 0.5);
  float cardLowerUV = clamp(edgeShape.x, 0.0, 1.0);
  float cardUpperUV = clamp(edgeShape.y, 0.0, 1.0);
  float bandBoost = clamp(edgeShape.z, 0.5, 2.0);
  float widthX = clamp(edgeShape.w, 0.3, 1.0);
  float topBandScale = max(0.0, edgeProfile.x);
  float bottomBandScale = max(0.0, edgeProfile.y);

  float pulse = 1.0 + pulseAmount * sin(cc_time.x * max(0.1, pulseSpeed));
  float topBandHeight = bandHeight * topBandScale;
  float bottomBandHeight = bandHeight * bottomBandScale;
  float distX = abs(v_uv0.x - 0.5) * 2.0;
  float widthFeather = max(edgeFeather, 0.04);
  float bandX = 1.0 - smoothstep(max(0.0, widthX - widthFeather), widthX, distX);

  float topEdgeGate = 1.0 - smoothstep(cardUpperUV, cardUpperUV + 0.008, v_uv0.y);
  float riseTop = max(0.0, cardUpperUV - v_uv0.y);
  vec4 topBand = sampleEdgeBand(riseTop, topBandHeight, widthX);
  float topEdge = topBand.a * topEdgeGate * bandX * bandBoost;

  float bottomEdgeGate = smoothstep(cardLowerUV - 0.008, cardLowerUV, v_uv0.y);
  float riseBottom = max(0.0, v_uv0.y - cardLowerUV);
  vec4 bottomBand = sampleEdgeBand(riseBottom, bottomBandHeight, widthX);
  float bottomEdge = bottomBand.a * bottomEdgeGate * bandX * bandBoost;

  float edgeMask = max(topEdge, bottomEdge);
  vec3 bandRgb = mix(bottomBand.rgb, topBand.rgb, step(bottomEdge, topEdge));
  vec3 glowRgb = glowColor.rgb * bandRgb * (glowAlpha * pulse * edgeMask * glowColor.a);

  #if USE_TEXTURE
    vec4 baseTex = texture2D(texture, v_uv0);
    #if CC_USE_ALPHA_ATLAS_TEXTURE
      baseTex.a *= texture2D(texture, v_uv0 + vec2(0.0, 0.5)).r;
    #endif
  #else
    vec4 baseTex = vec4(1.0);
  #endif
  float outAlpha = clamp(max(length(glowRgb), baseTex.a * 0.001), 0.0, 1.0);
  vec3 outRgb = outAlpha > 0.001 ? glowRgb / outAlpha : vec3(0.0);
  gl_FragColor = vec4(outRgb, outAlpha) * v_color;
}

